sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    var isEmergency = g_form.getValue('is_emergency_leave');


    var startDateMs = getDateFromFormat(newValue, g_user_date_format);

    // Get today's date in the browser and set to midnight for an accurate comparison
    var today = new Date();
    today.setHours(0, 0, 0, 0);

    // Compare the timestamp of the selected date against today's timestamp
    if (startDateMs < today.getTime() && isEmergency !== 'true') {
        g_form.addErrorMessage(
            'Start Date cannot be in the past unless Emergency Leave is selected.'
        );
        g_form.clearValue('start_date'); 
    }
}
